    "text-transform:none; letter-spacing:normal;}",
    ".btn-small:disabled{opacity:.5; cursor:default;}",
    ".btn-primary{background:var(--navy); color:#fff; border-color:var(--navy);}",
    "#memoTextarea{width:100%; min-height:6rem; font:inherit; font-size:.92rem; padding:.5rem;",
    "border:1px solid var(--line-strong); border-radius:.35rem; box-sizing:border-box; margin-top:.3rem;",
