    ".partner-toolbar-note{font-size:.8rem; color:var(--muted);}",
    ".reg-grid{display:grid; grid-template-columns:1fr 1fr; gap:10px 14px;}",
    "@media (max-width:700px){ .reg-grid{grid-template-columns:1fr;} }",
