    "/* ---- 本日の要対応ポップアップ・バージョン表示 ---- */",
    ".ver{font-size:.66rem; color:var(--muted); border:1px solid var(--line); border-radius:.3rem;",
    "padding:.02rem .3rem; margin-left:.45rem; vertical-align:middle; font-weight:400;}",
